     1→# ABOUTME: Sea of Nodes IR graph container for Chalk compiler
     2→# ABOUTME: Manages collection of IR nodes and provides JSON serialization for IR persistence
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Graph {
     8→    use Chalk::IR::Node;
     9→
    10→    field $nodes :reader;
    11→    field $entry :reader;
    12→    field $uses;  # Use-def map: node_id => [user_id1, user_id2, ...]
    13→
    14→    ADJUST {
    15→        $nodes = {};
    16→        $entry = undef;
    17→        $uses  = {};
    18→    }
    19→
    20→    method add_node($node) {
    21→        my $node_id = $node->id;
    22→        $nodes->{$node_id} = $node;
    23→
    24→        # Initialize use list for this node (empty initially)
    25→        $uses->{$node_id} //= [];
    26→
    27→        # Update use-def chains: for each input, add this node as a user
    28→        for my $input_id ( $node->inputs->@* ) {
    29→            next unless defined $input_id;  # Skip undefined inputs
    30→            $uses->{$input_id} //= [];
    31→            push $uses->{$input_id}->@*, $node_id;
