$graph3->add_node($start3);

my $const_a3 = Chalk::IR::Node->new(
    id => 'node_1',
    op => 'Constant',
    inputs => [],
    attributes => { value => 4, type => 'Int' }
);
$graph3->add_node($const_a3);

my $const_b3 = Chalk::IR::Node->new(
