        inputs => ['node_1', 'node_2'],
        attributes => {
            left => { op => 'NodeRef', node_id => 'node_1' },
            right => { op => 'NodeRef', node_id => 'node_2' }
        }
    );
    $graph->add_node($mul2);

    # Add: (a*b) + (a*b)
    my $add = Chalk::IR::Node->new(
        id => 'node_5',
        op => 'Add',
        inputs => ['node_3', 'node_4'],
        attributes => {
            left => { op => 'NodeRef', node_id => 'node_3' },
