    id => 'node_4',
    op => 'Add',
    inputs => ['node_1', 'node_2'],
    attributes => {
        left => { op => 'NodeRef', node_id => 'node_1' },
        right => { op => 'NodeRef', node_id => 'node_2' }
    }
);
$graph->add_node($add2);

# (a+b) + (a+b)
my $add3 = Chalk::IR::Node->new(
    id => 'node_5',
    op => 'Add',
    inputs => ['node_3', 'node_4'],
    attributes => {
        left => { op => 'NodeRef', node_id => 'node_3' },
        right => { op => 'NodeRef', node_id => 'node_4' }
    }
);
