cat > /tmp/extract_modules.py << 'EOF'
import re
import sys
from collections import defaultdict

# Read grep output from stdin
lines = []
for line in sys.stdin:
    lines.append(line.rstrip())

# Define pragmas to filter out
pragmas = {
    'strict', 'warnings', 'experimental', 'utf8', 'open', '5.42.0', '5.40.2',
    'v5.42', 'v5.40', 'lib', 'overload', 'feature', 'base', 'parent'
}

# Track modules and files
modules = defaultdict(lambda: {'files': set(), 'count': 0})

for line in lines:
    # Extract use statement
    match = re.search(r'use\s+(\S+)(?:\s|;|$)', line)
    if not match:
        continue

    module = match.group(1)

    # Skip pragmas and version requirements
    if module in pragmas or re.match(r'^v?\d+\.', module):
        continue

    # Extract file path
    file_match = re.match(r'^([^:]+):', line)
    if file_match:
        file_path = file_match.group(1)
        modules[module]['files'].add(file_path)
        modules[module]['count'] += 1

# Print results sorted by count
print("\nEXTERNAL NON-PRAGMA MODULES USED IN CHALK\n" + "="*60)
for module in sorted(modules.keys(), key=lambda x: modules[x]['count'], reverse=True):
    info = modules[module]
    print(f"\n{module}: {info['count']} uses")
    print(f"  Files:")
    for f in sorted(info['files']):
        print(f"    {f}")
EOF

