cat > /tmp/extract_modules.py << 'EOF'
import re
import sys
from collections import defaultdict

# Read the full grep output
input_text = sys.stdin.read()

# Define pragmas and things to filter out
pragmas = {
    'strict', 'warnings', 'experimental', 'utf8', 'open', '5.42.0', '5.40.2',
    'v5.42', 'v5.40', 'lib', 'overload', 'feature', 'base', 'parent', 'defer'
}

# Track modules and files
modules = defaultdict(lambda: {'files': set(), 'count': 0})

# Split by lines and process each
for line in input_text.split('\n'):
    if not line.strip():
        continue

    # Extract the use statement - look for 'use MODULENAME'
    match = re.search(r':\s*use\s+(\S+)', line)
    if not match:
        continue

    module = match.group(1).strip(';')

    # Skip pragmas and version requirements
    if module in pragmas or re.match(r'^(v?)[\d.]+', module):
        continue

    # Skip Chalk:: namespace
    if module.startswith('Chalk::'):
        continue

    # Extract file path
    file_match = re.match(r'^([^:]+):', line)
    if file_match:
        file_path = file_match.group(1)
        # Only count actual modules, not comments
        if 'use' in line and not line.strip().startswith('#'):
            modules[module]['files'].add(file_path)
            modules[module]['count'] += 1

# Print results sorted by count
print("\nEXTERNAL NON-PRAGMA MODULES USED IN CHALK (excluding Chalk:: modules)\n" + "="*70)
if not modules:
    print("No external modules found!")
else:
    for module in sorted(modules.keys(), key=lambda x: modules[x]['count'], reverse=True):
        info = modules[module]
        print(f"\n{module}")
        print(f"  Uses: {info['count']}")
        print(f"  Files:")
        for f in sorted(info['files']):
            # Make paths relative for readability
            short_path = f.replace('/Users/perigrin/dev/chalk/', '')
            print(f"    - {short_path}")
EOF

