     2→# ABOUTME: Implements GVN for common subexpression elimination and redundant computation removal
     3→
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→
     8→class Chalk::IR::Optimizer::GVN {
     9→    use Chalk::IR::Node;
    10→    use Chalk::IR::Graph;
    11→    use Digest::MD5 qw(md5_hex);
    12→    use Storable qw(freeze);
    13→
    14→    # Run Global Value Numbering optimization pass
    15→    # Returns: { graph => optimized_graph, metrics => { nodes_eliminated => N, redirections => {...} } }
    16→    sub run_gvn($class, $graph) {
    17→        # Value number tracking: value_number => canonical_node_id
    18→        my $value_to_node = {};
    19→
    20→        # Node to value number mapping: node_id => value_number
    21→        my $node_to_value = {};
    22→
    23→        # Redirection map: duplicate_node_id => canonical_node_id
    24→        my $redirections = {};
    25→
    26→        # Get all nodes in a consistent order (we'll process them by ID order)
    27→        my @node_ids = sort keys %{$graph->nodes};
    28→
    29→        # Phase 1: Compute value numbers for all nodes
    30→        for my $node_id (@node_ids) {
    31→            my $node = $graph->get_node($node_id);
    32→            next unless defined($node);
    33→
    34→            # Compute value number for this node
    35→            my $value_num = $class->_compute_value_number($node, $node_to_value, $graph);
    36→
    37→            # Check if we've seen this value number before
    38→            if (exists($value_to_node->{$value_num})) {
    39→                # Found a duplicate! Record the redirection
    40→                my $canonical_id = $value_to_node->{$value_num};
    41→                $redirections->{$node_id} = $canonical_id;
    42→                # Use the canonical node's value number for this node too
    43→                $node_to_value->{$node_id} = $value_num;
    44→            } else {
    45→                # First time seeing this value - this is the canonical node
    46→                $value_to_node->{$value_num} = $node_id;
    47→                $node_to_value->{$node_id} = $value_num;
    48→            }
    49→        }
    50→
    51→        # Phase 2: Build new graph with redirections applied
    52→        my $new_graph = Chalk::IR::Graph->new();
    53→
    54→        # Track which nodes have been copied to new graph
    55→        my %copied;
    56→
    57→        # Copy nodes that aren't redirected, applying redirections to inputs
    58→        for my $node_id (@node_ids) {
    59→            # Skip nodes that are being redirected away
    60→            next if exists($redirections->{$node_id});
    61→
    62→            my $old_node = $graph->get_node($node_id);
    63→            next unless defined($old_node);
    64→
    65→            # Apply redirections to input list
    66→            my @new_inputs;
    67→            for my $input_id ($old_node->inputs->@*) {
    68→                if (defined($input_id)) {
    69→                    # Follow redirection chain if this input was redirected
    70→                    my $final_id = $class->_follow_redirections($input_id, $redirections);
    71→                    push @new_inputs, $final_id;
    72→                } else {
    73→                    push @new_inputs, undef;
    74→                }
    75→            }
    76→
    77→            # Apply redirections to attributes (if they contain node references)
    78→            my $new_attributes = $class->_redirect_attributes(
    79→                $old_node->attributes,
    80→                $redirections
    81→            );
    82→
    83→            # Create new node with redirected inputs
    84→            my $new_node = Chalk::IR::Node->new(
    85→                id         => $node_id,
    86→                op         => $old_node->op,
    87→                inputs     => \@new_inputs,
    88→                attributes => $new_attributes,
    89→            );
    90→
    91→            $new_graph->add_node($new_node);
    92→            $copied{$node_id} = 1;
    93→        }
    94→
    95→        # Preserve entry point (following any redirection)
    96→        if (defined($graph->entry)) {
    97→            my $new_entry = $class->_follow_redirections($graph->entry, $redirections);
    98→            $new_graph->set_entry($new_entry);
    99→        }
